class BusBooking:

    def __init__(self, n):
        # cost[seat] = time that seat cost when it was booked (only booked seats are present)
        self.cost = {}
        # running sum of all values in self.cost
        self.total = 0

    def toggle(self, seat):
        # seat is already booked: free it and remove the cost it was booked with
        if seat in self.cost:
            self.total -= self.cost.pop(seat)
            return

        letter, row = seat[0], seat[1:]
        c = 1  # middle seats and undelayed window seats cost 1
        # a window seat costs 3 when its adjacent middle seat is already booked
        if letter == 'A' and ('B' + row) in self.cost:
            c = 3
        elif letter == 'D' and ('C' + row) in self.cost:
            c = 3

        self.cost[seat] = c
        self.total += c

    def getTotalTime(self):
        # total of the costs fixed at booking time
        return self.total

    def getMinTime(self):
        # best order: book all window seats before any middle seat, so every seat costs 1
        return len(self.cost)
